    pts=[(i,j) for i,r in enumerate(grid) for j,v in enumerate(r) if v==c]
    t=min(p[0] for p in pts); l=min(p[1] for p in pts)
    return [[grid[i][j] for j in range(l,max(p[1] for p in pts)+1)] for i in range(t,max(p[0] for p in pts)+1)]
def transform(grid):
    shape=bbox(grid,8)
    n=sum(v==4 for r in grid for v in r)
    return [row*n for row in shape]
